/* ---------- Туслах ---------- */
function toast(m){const t=document.getElementById("toast");t.textContent=m;t.style.display="block";clearTimeout(t._t);t._t=setTimeout(()=>t.style.display="none",2600)}
function openModal(h){document.getElementById("box").innerHTML=h;document.getElementById("modal").classList.add("open")}
function closeModal(){document.getElementById("modal").classList.remove("open")}
document.getElementById("modal").addEventListener("click",e=>{if(e.target.id==="modal")closeModal()});
function go(p){if(p==="post")fph=[];state.page=p;render()}
function needLogin(){if(!user){loginModal();return true}return false}

/* ---------- Нэвтрэлт ---------- */
function loginModal(){go("login")}
async function doLogin(){
  const u=lu.value.trim(),p=lp.value;
  if(FB)return fbLogin(u,p);
  if(state.lt==="admin"){
    if(u===ADMIN.u&&p===ADMIN.p)user={name:"Админ",id:"admin",role:"admin"};
    else return toast("Админы нэр эсвэл нууц үг буруу");
  }else{
    const x=users.find(z=>z.id===u.toUpperCase());
    if(!x||x.pw!==await hash(p,x.id))return toast("Код эсвэл нууц үг буруу");
    if(x.status==="blocked")return toast("Таны эрх админаар хаагдсан байна");
    x.last=now();saveU();user={name:x.name,id:x.id,role:"student"};
  }
  store.set("laf_user",user);state.page=isAdmin()?"admin":"home";render();toast("Тавтай морил, "+user.name)
}
async function doRegister(){
  const id=rid.value.trim().toUpperCase(),nm=rname.value.trim(),em=rmail.value.trim(),ph=rphone.value.trim(),p1=rp1.value,p2=rp2.value;
  const cm=/^(\d{2})[A-Z]\dNUM\d{4}$/.exec(id);
  if(!cm||2000+Number(cm[1])>new Date().getFullYear())return toast("Оюутны код буруу. Жишээ: 26B1NUM0486");
  if(nm.length<2)return toast("Нэрээ бичнэ үү");
  if(!/^\S+@\S+\.\S+$/.test(em))return toast("И-мэйл буруу байна");
  if(!/^\d{8}$/.test(ph))return toast("Утас 8 оронтой байх ёстой");
  if(p1.length<6)return toast("Нууц үг дор хаяж 6 тэмдэгт");
  if(p1!==p2)return toast("Нууц үг таарахгүй байна");
  if(FB)return fbRegister(id,nm,em,ph,p1);
  if(users.some(z=>z.id===id))return toast("Энэ код бүртгэлтэй байна");
  users.push({id,name:nm,email:em,phone:ph,pw:await hash(p1,id),status:"active",created:now(),last:now()});saveU();
  user={name:nm,id,role:"student"};store.set("laf_user",user);state.page="home";render();toast("Амжилттай бүртгэгдлээ!")
}
function logout(){if(FB){auth.signOut();state.page="home";return}user=null;localStorage.removeItem("laf_user");state.page="home";render()}


function loginPage(){
  const t=state.lt,ad=t==="admin",rg=t==="register";
  const T=(k,x)=>`<button class="${t===k?"on":""}" onclick="state.lt='${k}';render()">${x}</button>`;
  const F=(id,lab,ic,ty,ph)=>`<label>${lab}</label><div class="inp"><i>${ic}</i><input id="${id}" type="${ty||"text"}" placeholder="${ph||""}"></div>`;
  const form=rg?F("rid","Оюутны код *",SVG.card,"text","26B1NUM0486")+F("rname","Овог нэр *",SVG.user)+F("rmail","И-мэйл *",SVG.mail,"email","name@num.edu.mn")+F("rphone","Утас * (8 орон)",SVG.tel,"tel")
    +F("rp1","Нууц үг * (6+ тэмдэгт)",SVG.lock,"password")+F("rp2","Нууц үг давтах *",SVG.lock,"password")+`<button class="go" onclick="doRegister()">Бүртгүүлэх</button>`
    :`<label>${ad?"Админы нэр":"Оюутны код"}</label><div class="inp"><i>${SVG.user}</i><input id="lu" autocomplete="username" placeholder="${ad?"admin":"26B1NUM0486"}"></div>
    <label>Нууц үг</label><div class="inp"><i>${SVG.lock}</i><input id="lp" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter')doLogin()"><button class="eye" type="button" onclick="lp.type=lp.type==='password'?'text':'password'">Харах</button></div>
    <button class="go" onclick="doLogin()">Нэвтрэх</button>
    <p class="meta" style="margin-top:14px">${ad?"Демо админ: <b>admin</b> / <b>admin123</b>":"Бүртгэлгүй бол дээрх <b>Бүртгүүлэх</b> табыг сонгоно уу."}</p>`;
  return `<div class="auth-wrap"><div class="auth-l">
   <div class="top">Та Монгол Улсын Их Сургуулийн Lost &amp; Found системд тавтай морилно уу.</div>
   <div class="mid"><img class="lg" src="${A.LOGO_NAVY}" alt="Монгол Улсын Их Сургууль">
    <div class="lt">${T("student","Нэвтрэх")}${T("register","Бүртгүүлэх")}${T("admin","Админ")}</div>${form}</div>
   <div class="foot"><a onclick="go('home')">Нүүр хуудас руу буцах</a></div></div>
   <div class="auth-r"><h2>Алдсан зүйлээ олж,<br>олсон зүйлээ эзэнд нь өгье</h2><p>Сургуулийн бүх байрны алдагдсан эд зүйлийг нэг дор бүртгэж, баталгаажуулан буцаана.</p>
   <ul><li>Зураг, тайлбартай зар оруулна</li><li>Ангилал, байршлаар хайна</li><li>Админ шалгаж, эзэнд нь аюулгүй хүлээлгэн өгнө</li></ul></div></div>`;
}
/* ---------- Навигаци ---------- */
function renderNav(){
  const b=(p,t)=>`<button class="${state.page===p?"on":""}" onclick="go('${p}')">${t}</button>`;
  let h=b("home","Нүүр")+`<button onclick="if(!needLogin())go('post')" class="${state.page==="post"?"on":""}">+ Зар оруулах</button>`;
  if(user&&!isAdmin()){const un=myNotifs().filter(n=>!n.read).length;h+=b("mine","Миний зар")+`<button class="${state.page==="notifs"?"on":""}" onclick="go('notifs')">Мэдэгдэл${un?`<span class="bdg">${un}</span>`:""}</button>`}
  if(isAdmin())h+=b("admin","Админ хяналт");
  h+=user?`<button onclick="logout()">${esc(user.name)} · Гарах</button>`:`<button onclick="go('login')" style="background:#fff;color:var(--navy)">Нэвтрэх</button>`;
  document.getElementById("nav").innerHTML=h;
}

/* ---------- Нүүр ---------- */
function card(p){
  return `<div class="card" onclick="detail(${p.id})"><div class="ph">${p.img?`<img src="${p.img}" alt="">`:ICON[p.cat]||ICON["Бусад"]}${imgsOf(p).length>1?`<span class="cnt">${imgsOf(p).length} зураг</span>`:""}</div>
  <div class="cb"><span class="tag t-${p.type}">${p.type==="lost"?"Алдсан":"Олсон"}</span>
  ${p.status==="returned"?'<span class="tag s-returned">Эзэнд нь өгсөн</span>':""}
  <h3>${esc(p.title)}</h3><div class="meta">Байршил: ${esc(p.place)}<br>Огноо: ${esc(p.date)} · ${esc(p.cat)}</div></div></div>`;
}
function home(){
  const cnt=t=>posts.filter(p=>p.status==="approved"&&(t==="all"||p.type===t)).length;
  return `<div class="hero"><h1>Алдсан зүйлээ олоорой, олсон зүйлээ эзэнд нь өгөөрэй</h1>
  <p>Сургуулийн байрууд дахь алдагдсан болон олдсон эд зүйлийг нэг дор бүртгэж, хайж, баталгаажуулан буцаана.</p><div class="cta"><button onclick="if(!needLogin())go('post')">+ Зар оруулах</button><button class="o" onclick="document.getElementById('fq').focus()">Хайх</button></div></div>
  <div class="filters">
   <input id="fq" placeholder="Нэр, тайлбараар хайх" value="${esc(state.q)}" oninput="state.q=this.value;list()">
   <select onchange="state.cat=this.value;list()"><option value="">Бүх ангилал</option>${CATS.map(c=>`<option ${state.cat===c?"selected":""}>${c}</option>`).join("")}</select>
   <input placeholder="Байршил" value="${esc(state.loc)}" oninput="state.loc=this.value;list()">
   <button class="ghost" onclick="state.q=state.cat=state.loc='';render()">Цэвэрлэх</button></div>
  <div class="tabs">${[["all","Бүгд"],["lost","Алдсан"],["found","Олсон"]].map(([k,t])=>`<button class="${state.tab===k?"on":""}" onclick="state.tab='${k}';render()">${t} (${cnt(k)})</button>`).join("")}</div>
  <div class="grid" id="list"></div>`;
}
function list(){
  const q=state.q.toLowerCase(),l=state.loc.toLowerCase();
  const r=posts.filter(p=>["approved","returned"].includes(p.status)&&(state.tab==="all"||p.type===state.tab)&&(!state.cat||p.cat===state.cat)
    &&(!q||(p.title+p.desc).toLowerCase().includes(q))&&(!l||p.place.toLowerCase().includes(l))).sort((a,b)=>b.id-a.id);
  document.getElementById("list").innerHTML=r.length?r.map(card).join(""):'<div class="empty" style="grid-column:1/-1">Илэрц олдсонгүй</div>';
}
function detail(id){
  const p=posts.find(x=>x.id===id);if(!p)return;
  const canClaim=p.status==="approved";
  const im=imgsOf(p);
  openModal(`${im.length?`<img class="big" id="bigimg" src="${im[0]}" alt="">${im.length>1?`<div class="thumbs">${im.map((s,i)=>`<img class="${i?"":"on"}" src="${s}" alt="" onclick="bigimg.src=this.src;document.querySelectorAll('.thumbs img').forEach(x=>x.classList.remove('on'));this.classList.add('on')">`).join("")}</div>`:""}`:`<div class="ph" style="border-radius:10px;margin-bottom:8px">${ICON[p.cat]||ICON["Бусад"]}</div>`}
  <span class="tag t-${p.type}">${p.type==="lost"?"Алдсан":"Олсон"}</span>
  <h2 style="margin:8px 0">${esc(p.title)}</h2>
  <p class="meta">Байршил: ${esc(p.place)} · Огноо: ${esc(p.date)} · ${esc(p.cat)}</p>
  <p>${esc(p.desc)||"—"}</p>
  <p class="meta">Холбоо барих мэдээллийг аюулгүй байдлын үүднээс админ баталгаажуулсны дараа өгнө.</p>
  ${canClaim?`<label>${p.type==="found"?"Энэ миний зүйл — эзэмшлийн баталгаа (онцлог тэмдэг, дотор нь юу байсан гэх мэт)":"Би энэ зүйлийг олсон — дэлгэрэнгүй тайлбар"}</label>
  <textarea id="cm"></textarea><label>Таны утас</label><input id="cp">
  <div style="display:flex;gap:8px;margin-top:14px"><button onclick="sendClaim(${p.id})" style="flex:1">${p.type==="found"?"Эзэн нь би гэж мэдэгдэх":"Олсон гэж мэдэгдэх"}</button><button class="ghost" onclick="closeModal()">Хаах</button></div>`
  :`<button class="ghost" onclick="closeModal()">Хаах</button>`}`);
}
function sendClaim(id){
  if(!user){closeModal();return go("login")}
  if(cm.value.trim().length<5||!cp.value.trim())return toast("Тайлбар болон утсаа бөглөнө үү");
  if(FB)return fbClaim(id);
  claims.push({id:Date.now(),postId:id,by:user.id,msg:cm.value.trim(),phone:cp.value.trim(),date:new Date().toLocaleString("mn-MN"),done:false});
  save();closeModal();toast("Хүсэлт админд илгээгдлээ")
}

