function toggleBlock(id){if(FB)return fbToggleBlock(id);const u=users.find(x=>x.id===id);if(u){u.status=u.status==="blocked"?"active":"blocked";saveU();render();toast(u.status==="blocked"?"Гишүүний эрх хаагдлаа":"Гишүүний эрх нээгдлээ")}}
async function resetPw(id){
  const u=users.find(x=>x.id===id);if(!u)return;
  const p=prompt(u.name+" — шинэ нууц үг (6+ тэмдэгт):");if(!p)return;
  if(p.length<6)return toast("Нууц үг дор хаяж 6 тэмдэгт");
  u.pw=await hash(p,u.id);saveU();toast("Нууц үг шинэчлэгдлээ")
}
function delUser(id){
  const u=users.find(x=>x.id===id);if(!u||!confirm(u.name+" ("+id+") гишүүнийг устгах уу?"))return;
  if(confirm("Түүний оруулсан зар болон хүсэлтийг бас устгах уу?\nOK = устгана, Cancel = зарууд хэвээр үлдэнэ")){
    const ids=posts.filter(p=>p.owner===id).map(p=>p.id);posts=posts.filter(p=>p.owner!==id);claims=claims.filter(c=>c.by!==id&&!ids.includes(c.postId));save()}
  users=users.filter(x=>x.id!==id);saveU();render();toast("Гишүүн устгагдлаа")
}


/* ---------- Мэдэгдэл + Устгах хүсэлт ---------- */
const tok=s=>new Set(String(s||"").toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w=>w.length>=3));
function matchScore(a,b){
  const ta=tok(a.title+" "+a.desc),tb=tok(b.title+" "+b.desc);let c=0;ta.forEach(w=>{if(tb.has(w))c++});
  if(!c)return 0;
  let s=Math.min(c,3)*2;if(a.cat===b.cat)s+=2;
  const pa=tok(a.place),pb=tok(b.place);let pc=0;pa.forEach(w=>{if(pb.has(w))pc++});if(pc)s+=1;
  if(Math.abs(new Date(a.date)-new Date(b.date))/864e5<=14)s+=1;
  return s;
}
function buildNotifs(p,s){
  const out=[],d=now(),base=Date.now();let k=0;
  const add=(to,text,postId,key)=>{if(!to)return;out.push({id:key||("n"+base+"_"+(k++)),to,text,postId,date:d,ts:base+k,read:false})};
  const msg={approved:`Таны "${p.title}" зар батлагдаж нийтлэгдлээ`,rejected:`Таны "${p.title}" зарыг админ нийтлэлээс хаслаа`,returned:`Таны "${p.title}" зар "эзэнд нь өгсөн" гэж тэмдэглэгдлээ`}[s];
  if(msg)add(p.owner,msg,p.id);
  if(s==="approved"){
    posts.filter(q=>q.id!==p.id&&q.status==="approved"&&q.type!==p.type&&q.owner!==p.owner&&matchScore(p,q)>=5).forEach(q=>{
      const lost=p.type==="lost"?p:q,found=p.type==="lost"?q:p;
      add(lost.owner,`Таны алдсан "${lost.title}"-тэй төстэй зүйл олдсон байж магадгүй: "${found.title}" (${found.place}). Зар дээр дарж шалгаад, таных мөн бол "Эзэн нь би" гэж мэдэгдээрэй.`,found.id,`m_${lost.id}_${found.id}_L`);
      add(found.owner,`Таны олсон "${found.title}"-тэй төстэй алдсан зар байна: "${lost.title}"`,lost.id,`m_${lost.id}_${found.id}_F`);
    });
  }
  return out;
}
async function pushNotifs(list){
  list=list.filter(n=>!notifs.some(x=>x.id===n.id));if(!list.length)return;
  if(FB){try{const b=fs.batch();list.forEach(n=>b.set(fs.collection("notifications").doc(n.id),n));await b.commit()}catch(e){console.warn("notify",e.message)}}
  else{notifs.push(...list);saveN()}
}
const myNotifs=()=>notifs.filter(n=>n.to===me()).sort((a,b)=>(b.ts||0)-(a.ts||0));
function notifsView(){
  const r=myNotifs();
  return `<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px"><h2>Мэдэгдэл</h2>${r.some(n=>!n.read)?`<button class="sm ghost" onclick="readAll()">Бүгдийг уншсан болгох</button>`:""}</div>`
   +(r.length?r.map(n=>`<div class="item nitem ${n.read?"":"new"}" style="cursor:pointer" onclick="openNotif('${n.id}')"><div class="info">${n.read?"":'<span class="tag s-approved">Шинэ</span> '}${esc(n.text)}<div class="meta">${esc(n.date)}</div></div></div>`).join(""):'<div class="empty">Мэдэгдэл алга</div>');
}
async function markRead(list){
  list=list.filter(n=>!n.read);if(!list.length)return;
  list.forEach(n=>n.read=true);
  if(FB){try{const b=fs.batch();list.forEach(n=>b.update(fs.collection("notifications").doc(n.id),{read:true}));await b.commit()}catch(e){console.warn(e.message)}}
  else saveN();
}
async function readAll(){await markRead(myNotifs());render()}
async function openNotif(id){
  const n=notifs.find(x=>x.id===id);if(!n)return;
  await markRead([n]);render();
  if(n.postId&&posts.find(p=>p.id===n.postId))detail(n.postId);
}
/* --- Хэрэглэгч: устгах хүсэлт --- */
function delReqModal(id){
  const p=posts.find(x=>x.id===id);if(!p)return;
  openModal(`<h2 style="margin-top:0">Зар устгах хүсэлт</h2>
  <p class="meta">"${esc(p.title)}" зарыг яагаад устгуулах гэж байгаагаа бичнэ үү. Хүсэлтийг админ хянаж шийднэ.</p>
  <label>Шалтгаан *</label><select id="drs"><option>Эд зүйлээ олсон / буцаан авсан</option><option>Алдсан зүйл өөр аргаар олдсон</option><option>Буруу мэдээлэл оруулсан</option><option>Давхардсан зар</option><option>Бусад</option></select>
  <label>Нэмэлт тайлбар <span style="color:var(--mut)">("Бусад" бол заавал)</span></label><textarea id="drx"></textarea>
  <div style="display:flex;gap:8px;margin-top:14px"><button onclick="submitDelReq(${id})" style="flex:1">Хүсэлт илгээх</button><button class="ghost" onclick="closeModal()">Болих</button></div>`);
}
async function submitDelReq(id){
  const p=posts.find(x=>x.id===id);if(!p)return;
  const t=drx.value.trim();
  if(drs.value==="Бусад"&&t.length<5)return toast("Шалтгаанаа бичнэ үү");
  if(delreqs.some(r=>r.postId===id&&r.status==="pending"))return toast("Хүсэлт өмнө нь илгээгдсэн байна");
  const r={id:String(Date.now()),postId:id,title:p.title,by:me(),byCode:user.id,reason:drs.value+(t?" - "+t:""),date:now(),status:"pending",note:""};
  if(FB){try{await fs.collection("delreqs").doc(r.id).set(r)}catch(e){return toast("Илгээж чадсангүй: "+fbErr(e))}}
  else{delreqs.push(r);saveN()}
  closeModal();render();toast("Устгах хүсэлт админд илгээгдлээ");
}
/* --- Админ: устгах хүсэлт шийдэх --- */
function delreqView(){
  const r=[...delreqs].sort((a,b)=>b.id-a.id);
  if(!r.length)return '<div class="empty">Устгах хүсэлт алга</div>';
  const L={pending:"Хүлээгдэж буй",approved:"Устгасан",rejected:"Татгалзсан"},C={pending:"s-pending",approved:"s-returned",rejected:"s-rejected"};
  return r.map(q=>{const p=posts.find(x=>x.id===q.postId);return `<div class="item"><div class="info"><b>${esc(q.title)}</b> <span class="tag ${C[q.status]}">${L[q.status]}</span>
   <p style="margin:6px 0">Шалтгаан: ${esc(q.reason)}</p><div class="meta">Хүсэлт гаргасан: ${esc(q.byCode||q.by)} · ${esc(q.date)}${q.note?" · Админы тайлбар: "+esc(q.note):""}${p?"":" · (зар одоо байхгүй)"}</div></div>
   ${q.status==="pending"?`<div class="acts"><button class="sm bad" onclick="approveDel('${q.id}')">Зөвшөөрч устгах</button><button class="sm ghost" onclick="rejectDel('${q.id}')">Татгалзах</button></div>`:""}</div>`}).join("");
}
async function approveDel(id){
  const q=delreqs.find(r=>r.id===id);if(!q||!confirm('"'+q.title+'" зарыг устгах уу?'))return;
  const note={id:"d_"+q.id,to:q.by,text:`"${q.title}" зарыг устгах хүсэлтийг тань зөвшөөрч, зарыг устгалаа`,postId:0,date:now(),ts:Date.now(),read:false};
  if(FB){
    try{const b=fs.batch();b.delete(fs.collection("posts").doc(String(q.postId)));b.delete(fs.collection("private").doc(String(q.postId)));
      claims.filter(c=>c.postId===q.postId).forEach(c=>b.delete(fs.collection("claims").doc(String(c.id))));
      b.update(fs.collection("delreqs").doc(q.id),{status:"approved"});await b.commit();await pushNotifs([note]);toast("Зар устгагдлаа")}
    catch(e){toast(fbErr(e))}
  }else{
    posts=posts.filter(p=>p.id!==q.postId);claims=claims.filter(c=>c.postId!==q.postId);q.status="approved";save();pushNotifs([note]);saveN();render();toast("Зар устгагдлаа")
  }
}
async function rejectDel(id){
  const q=delreqs.find(r=>r.id===id);if(!q)return;
  const n=prompt("Татгалзсан шалтгаан (заавал биш):");if(n===null)return;
  const note={id:"d_"+q.id,to:q.by,text:`"${q.title}" зарыг устгах хүсэлтийг тань татгалзлаа${n.trim()?": "+n.trim():""}`,postId:q.postId,date:now(),ts:Date.now(),read:false};
  if(FB){try{await fs.collection("delreqs").doc(q.id).update({status:"rejected",note:n.trim()});await pushNotifs([note]);toast("Татгалзлаа")}catch(e){toast(fbErr(e))}}
  else{q.status="rejected";q.note=n.trim();saveN();pushNotifs([note]);render();toast("Татгалзлаа")}
}

/* ---------- FIREBASE (дундын өгөгдлийн сан) ---------- */
let auth,fs,unsubs=[],regBusy=false,rt;
const MAILD="@num-lostfound.app",mailOf=c=>String(c).trim().toLowerCase()+MAILD;
const maps={pub:new Map(),mine:new Map(),all:new Map(),priv:new Map()};
const fbErr=e=>({"permission-denied":"Эрх хүрэхгүй байна","unavailable":"Сүлжээ тасарсан"}[e.code]||e.code||"алдаа");
function recompute(){
  const m=new Map();
  for(const k of ["pub","mine","all"])maps[k].forEach((v,id)=>m.set(id,{...m.get(id),...v}));
  posts=[...m.values()].map(p=>({...p,...(maps.priv.get(String(p.id))||{})})).sort((a,b)=>a.id-b.id);
  clearTimeout(rt);rt=setTimeout(()=>{
    const ae=document.activeElement,typing=ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName);
    if(document.getElementById("modal").classList.contains("open")||["post","login"].includes(state.page))return;
    if(typing){if(state.page==="home")list();return}
    render()},120);
}
function listen(){
  unsubs.forEach(f=>f());unsubs=[];Object.values(maps).forEach(m=>m.clear());
  const col=n=>fs.collection(n),err=n=>e=>console.warn(n,e.message);
  const watch=(q,key)=>unsubs.push(q.onSnapshot(s=>{const m=maps[key];m.clear();s.forEach(d=>m.set(d.id,d.data()));recompute()},err(key)));
  if(isAdmin()){
    watch(col("posts"),"all");watch(col("private"),"priv");
    unsubs.push(col("claims").onSnapshot(s=>{claims=s.docs.map(d=>d.data()).sort((a,b)=>a.id-b.id);recompute()},err("claims")));
    unsubs.push(col("users").onSnapshot(s=>{users=s.docs.map(d=>({...d.data(),uid:d.id}));recompute()},err("users")));
    unsubs.push(col("notifications").onSnapshot(s=>{notifs=s.docs.map(d=>d.data());recompute()},err("notifications")));
    unsubs.push(col("delreqs").onSnapshot(s=>{delreqs=s.docs.map(d=>d.data());recompute()},err("delreqs")));
  }else{
    watch(col("posts").where("status","in",["approved","returned"]),"pub");
    if(user){watch(col("posts").where("owner","==",user.uid),"mine");watch(col("private").where("owner","==",user.uid),"priv");
      unsubs.push(col("notifications").where("to","==",user.uid).onSnapshot(s=>{const o=notifs.filter(n=>!n.read).length;notifs=s.docs.map(d=>d.data());const c=notifs.filter(n=>!n.read).length;if(c>o)toast("Шинэ мэдэгдэл ирлээ");recompute()},err("notifications")));
      unsubs.push(col("delreqs").where("by","==",user.uid).onSnapshot(s=>{delreqs=s.docs.map(d=>d.data());recompute()},err("delreqs")))}
  }
}
async function startSession(u){
  const d=await fs.collection("users").doc(u.uid).get();
  if(!d.exists){await auth.signOut();toast("Бүртгэл олдсонгүй");return false}
  const x=d.data();
  if(x.status==="blocked"){await auth.signOut();toast("Таны эрх админаар хаагдсан байна");return false}
  user={name:x.name,id:x.id,uid:u.uid,role:x.role==="admin"?"admin":"student"};
  if(user.role!=="admin")fs.collection("users").doc(u.uid).update({last:now()}).catch(()=>{});
  listen();return true;
}
function initFB(){
  firebase.initializeApp(FIREBASE_CONFIG);auth=firebase.auth();fs=firebase.firestore();listen();
  auth.onAuthStateChanged(async u=>{
    if(regBusy)return;
    if(!u){user=null;users=[];claims=[];notifs=[];delreqs=[];listen();if(["mine","admin","post"].includes(state.page))state.page="home";return render()}
    const fromLogin=state.page==="login";
    try{if(!(await startSession(u)))return}catch(e){return toast("Нэвтэрч чадсангүй: "+fbErr(e))}
    if(fromLogin&&state.lt==="admin"&&!isAdmin()){await auth.signOut();return toast("Админы эрхгүй байна")}
    if(fromLogin){state.page=isAdmin()?"admin":"home";toast("Тавтай морил, "+user.name)}
    render();
  });
}
async function fbLogin(u,p){
  if(!u||!p)return toast("Нэр, нууц үгээ оруулна уу");
  try{await auth.signInWithEmailAndPassword(mailOf(u),p)}
  catch(e){toast(e.code==="auth/too-many-requests"?"Олон удаа буруу оруулсан. Түр хүлээнэ үү":"Код эсвэл нууц үг буруу")}
}
async function fbRegister(id,nm,em,ph,p1){
  regBusy=true;
  try{
    const c=await auth.createUserWithEmailAndPassword(mailOf(id),p1);
    try{await fs.collection("users").doc(c.user.uid).set({id,name:nm,email:em,phone:ph,role:"student",status:"active",created:now(),last:now()})}
    catch(e){try{await c.user.delete()}catch(_){}throw e}
    await startSession(c.user);state.page="home";render();toast("Амжилттай бүртгэгдлээ!")
  }catch(e){toast(e.code==="auth/email-already-in-use"?"Энэ код бүртгэлтэй байна":"Бүртгэл амжилтгүй: "+fbErr(e))}
  finally{regBusy=false}
}
async function fbSubmit(){
  const id=Date.now();
  const pub={id,type:ft.value,title:ftitle.value.trim(),cat:fcat.value,place:fplace.value.trim(),date:fdate.value,desc:fdesc.value.trim(),img:fph[0]||"",imgs:[...fph],owner:user.uid,ownerCode:user.id,status:"pending"};
  const priv={id,owner:user.uid,contact:fcontact.value.trim(),secret:fsecret.value.trim()};
  try{const b=fs.batch();b.set(fs.collection("posts").doc(String(id)),pub);b.set(fs.collection("private").doc(String(id)),priv);await b.commit();
    fph=[];toast("Зар админд шалгуулахаар илгээгдлээ");go("mine")}
  catch(e){toast("Илгээж чадсангүй: "+fbErr(e))}
}
async function fbClaim(id){
  const c={id:Date.now(),postId:id,by:user.uid,byCode:user.id,msg:cm.value.trim(),phone:cp.value.trim(),date:now(),done:false};
  try{await fs.collection("claims").doc(String(c.id)).set(c);closeModal();toast("Хүсэлт админд илгээгдлээ")}
  catch(e){toast("Илгээж чадсангүй: "+fbErr(e))}
}
async function fbSetStatus(id,s){
  const p=posts.find(x=>x.id===id);
  try{await fs.collection("posts").doc(String(id)).update({status:s});toast(STATUS[s]);if(p)pushNotifs(buildNotifs({...p,status:s},s))}
  catch(e){toast(fbErr(e))}
}
async function fbDelPost(id){
  if(!confirm("Энэ зарыг бүрмөсөн устгах уу?"))return;
  try{const b=fs.batch();b.delete(fs.collection("posts").doc(String(id)));b.delete(fs.collection("private").doc(String(id)));
    claims.filter(c=>c.postId===id).forEach(c=>b.delete(fs.collection("claims").doc(String(c.id))));await b.commit();toast("Устгагдлаа")}
  catch(e){toast(fbErr(e))}
}
function fbClaimDone(id){fs.collection("claims").doc(String(id)).update({done:true}).catch(e=>toast(fbErr(e)))}
function fbToggleBlock(id){
  const u=users.find(x=>x.id===id);if(!u)return;
  const s=u.status==="blocked"?"active":"blocked";
  fs.collection("users").doc(u.uid).update({status:s}).then(()=>toast(s==="blocked"?"Гишүүний эрх хаагдлаа":"Гишүүний эрх нээгдлээ")).catch(e=>toast(fbErr(e)));
}
/* ---------- Render ---------- */
function render(){
  if(!FB&&user&&user.role==="student"){const x=users.find(z=>z.id===user.id);if(!x||x.status==="blocked"){const b=x&&x.status==="blocked";user=null;localStorage.removeItem("laf_user");state.page="home";if(b)setTimeout(()=>toast("Таны эрх админаар хаагдсан байна"),50)}}
  document.body.classList.toggle("auth",state.page==="login");
  renderNav();
  const v=document.getElementById("view");
  if(["post","mine","admin","notifs"].includes(state.page)&&!user){state.page="home"}
  v.innerHTML=state.page==="login"?loginPage():state.page==="notifs"?notifsView():state.page==="post"?postForm():state.page==="mine"?mine():state.page==="admin"?admin():home();
  if(state.page==="home")list();
  window.scrollTo(0,0);
}
document.getElementById("hicon").src=A.ICON_WHITE;
if(!FB)document.querySelector("footer").insertAdjacentHTML("beforeend","<br><small>Демо горим: өгөгдөл зөвхөн энэ төхөөрөмжид хадгалагдана</small>");
render();
if(FB)initFB();

/* ---------- Small UX helpers ---------- */
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    const modal = document.getElementById("modal");
    if (modal?.classList.contains("open") && typeof closeModal === "function") {
      closeModal();
    }
  }
});

document.getElementById("modal")?.addEventListener("click", (event) => {
  if (event.target.id === "modal" && typeof closeModal === "function") {
    closeModal();
  }
});
